from flask_jwt_extended import jwt_required, get_jwt_identity
from datetime import datetime
from sqlalchemy import or_, and_
from models import db, User, Task, Category, Priority
from auth import create_user_token, authenticate_user, register_user

api = Blueprint('api', __name__, url_prefix='/api')

# Auth Routes

@api.route('/auth/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'email', 'password')):
        return jsonify({'error': 'Missing required fields'}), 400

    user, error = register_user(data['username'], data['email'], data['password'])
    if error:
        return jsonify({'error': error}), 400

    token = create_user_token(user)
    return jsonify({
        'message': 'User registered successfully',
        'user': user.to_dict(),
        'access_token': token
    }), 201

@api.route('/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or not all(k in data for k in ('username', 'password')):
        return jsonify({'error': 'Missing username or password'}), 400

    user = authenticate_user(data['username'], data['password'])
    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_user_token(user)
    return jsonify({
        'message': 'Login successful',
        'user': user.to_dict(),
        'access_token': token
    }), 200

# Category Routes

@api.route('/categories', methods=['GET'])
@jwt_required()
def get_categories():
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 10, type=int)

    pagination = Category.query.paginate(page=page, per_page=per_page)
    return jsonify({
        'categories': [c.to_dict() for c in pagination.items],
        'total': pagination.total,
        'pages': pagination.pages,
        'current_page': page
    }), 200

@api.route('/categories', methods=['POST'])
@jwt_required()
def create_category():
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'Missing category name'}), 400

    if Category.query.filter_by(name=data['name']).first():
        return jsonify({'error': 'Category already exists'}), 400

    category = Category(
        name=data['name'],
        description=data.get('description')
    )
    db.session.add(category)
    db.session.commit()
    return jsonify(category.to_dict()), 201

@api.route('/categories/<int:category_id>', methods=['GET'])
@jwt_required()
def get_category(category_id):
    category = Category.query.get_or_404(category_id)
