        task = response.get_json()
        task_id = task['id']

        response = client.get(f'/api/tasks/{task_id}')
        assert response.status_code == 200
        assert response.get_json()['title'] == task_data['title']

        response = client.put(
            f'/api/tasks/{task_id}',
            json={'status': 'in_progress'}
        )
